import{_ as t,o as e,c as a,ag as _}from"./chunks/framework.DaAXJYxM.js";const u=JSON.parse('{"title":"第102章 一个钟头","description":"","frontmatter":{},"headers":[],"relativePath":"第102章_一个钟头.md","filePath":"第102章_一个钟头.md"}'),o={name:"第102章_一个钟头.md"};function r(n,p,s,c,i,d){return e(),a("div",null,[...p[0]||(p[0]=[_('<h1 id="第102章-一个钟头" tabindex="-1">第102章 一个钟头 <a class="header-anchor" href="#第102章-一个钟头" aria-label="Permalink to &quot;第102章 一个钟头&quot;">​</a></h1><p>那个周六我们见了一次面，一个钟头。</p><p>那天晚上我们在手机上说了三个钟头四十分钟。</p><p>这个对比我后来一直记得。</p><p>我把它写下来是因为它太准确了。</p><p>我们两个人在一张桌子上，用一个钟头讲了分装、贴单、错件、钱怎么走。</p><p>那一个钟头里，我们一句话也没多说。</p><p>她讲了三次&quot;这个你知道了就往下&quot;。</p><p>我讲了两次&quot;好&quot;。</p><p>其他全在单子上。</p><p>那天晚上十一点，她上线了。</p><p>她第一句是：你今天很累吧。</p><p>我说，我不累。</p><p>她说，你坐那个椅子的样子很像累。</p><p>我说，我不累，我是不知道手放哪儿。</p><p>她说，你现在手放哪儿。</p><p>我说，我在打字。</p><p>她说，你就讲今天。</p><p>我说，今天我看见你手上戴了一块表。</p><p>她说，哦那个。</p><p>她说，那是我大三那年在校门口摊上买的，十二块。</p><p>她说，它不走。</p><p>我说，它不走你戴它。</p><p>她说，因为我戴它我就能记住时间大概在哪儿。</p><p>她说，我这边手机容易没电，我一看表，我知道我现在戴了六个小时，那我大概下午三点了。</p><p>她说，这个表它不走，可是它转。</p><p>她说，一天转两圈，我数圈。</p><p>我说，你数圈数了几年。</p><p>她说，两年半。</p><p>我说，那你比谁都准。</p><p>她说，我比谁都累。</p><p>她说，因为你戴一块不走的表，你每次看它都要想一次现在到底几点。</p><p>她说，别人看一眼就知道。</p><p>她说，我一天要看二十几次。</p><p>她说，我今天在你面前抬手看了三次。</p><p>我说，我知道，我数了。</p><p>她说，你别数。</p><p>我说，我数了你今天抬手三次，你低头看单子五次，你把那杯东西转了两次，你看了七次窗外。</p><p>她说，闻迟。</p><p>她说，你今天下午坐在我对面一个小时，你干的事是统计我。</p><p>我说，我不是统计你。</p><p>她说，你就是。</p><p>她说，你这个人你没办法。</p><p>她说，我早就知道你没办法，我今天还是找你。</p><p>我说，那你现在知道更清楚了。</p><p>她说，我现在知道得更清楚，我今天晚上还是在这儿跟你讲话。</p><p>她说，这就是问题。</p><p>她说，我今天晚上讲这些是错的。</p><p>我说，为什么。</p><p>她说，因为我今天在你面前坐了一个钟头，我一句话没讲那些。</p><p>她说，我今天晚上回来，我把那个杯子拿出来了。</p><p>我说，什么杯子。</p><p>她说，我今天下午走的时候，我把那个杯盖留在你那儿了。</p><p>她说，我回去我越想越难受。</p><p>我说，一个杯盖。</p><p>她说，不是杯盖。</p><p>她说，是我今天下午走的时候，我把手里那个杯盖放进你那个包的外袋里了。</p><p>她说，我进去之前我是空手的。</p><p>她说，我出来的时候我是空手的。</p><p>她说，中间那个东西在你那儿。</p><p>她说，我今天晚上在屋里来回走了四十分钟。</p><p>我说，你想拿回去。</p><p>她说，我不想拿回去。</p><p>她说，我要是想拿回去我今天上午就跟你讲了。</p><p>我说，那你难受什么。</p><p>她说，我难受的是我做了这件事。</p><p>她说，我这一辈子做了事，我不敢认。</p><p>她说，我今天下午在你对面坐了六十分钟，我一句话不讲，我手上做了这一件事。</p><p>她说，我今天晚上要是跟你讲了，我就得承认我今天下午是来干嘛的。</p><p>她说，我跟自己讲我是来谈钱的。</p><p>她说，现在我跟你讲了，我就骗不了自己了。</p><p>我坐在那儿，很久。</p><p>我说，那你说清楚你来干嘛。</p><p>她说，我不说。</p><p>我说，为什么。</p><p>她说，因为我一说，你今晚就要开始回。</p><p>她说，你一回我明天就要开始想我怎么回你。</p><p>她说，我今天有一百二十个件要发。</p><p>她说，你把这个东西留在这儿，我们两个今天晚上都难受。</p><p>她说，难受一晚上，我明天还能发。</p><p>她说，我要是今天讲了，我明天一整天都在算你昨天那句话。</p><p>她说，我不划算。</p><p>那天夜里十一点五十八，她最后发了一句。</p><p>她说，那个杯盖你别扔。</p><p>我说，我不扔。</p><p>她说，你放哪儿。</p><p>我说，我放桌上。</p><p>她说，你别放桌上。</p><p>她说，你放桌上你每天看见，你每天看见你今天晚上就要开始想。</p><p>她说，你想多了你就会讲。</p><p>她说，你把它放进你那个抽屉。</p><p>我说，为什么是抽屉。</p><p>她说，因为你的抽屉你不会天天开。</p><p>她说，你放到明天你就不难受了。</p><p>我说，那你呢。</p><p>她说，我不用放。</p><p>她说，我今天晚上已经走了四十分钟了。</p><p>她说，我明天起来我就好了。</p><p>我说，你明天一定会好吗。</p><p>她说，不一定。</p><p>她说，但是我不需要它一定。</p><p>她说，我需要它不要变成我们俩的一个东西。</p><p>那天夜里我把那个杯盖放进抽屉。</p><p>我放进去之前，我拿纸把它包了一下。</p><p>我包它是因为它是塑料的，塑料碰上铁会响。</p><p>我不想每天早上被一个杯盖响醒。</p><p>第二天早上我七点起，我拿东西的时候，抽屉里那个纸包在。</p><p>我没有打开。</p><p>我那天上午发了十九个件。</p><p>那个月末陈树到我这屋里拿一个东西。</p><p>他拉我抽屉找螺丝刀。</p><p>他拉开了，他看见那个纸包。</p><p>他说，你抽屉里放个纸包干什么。</p><p>我说，没什么。</p><p>他把抽屉推回去一半，又拉开。</p><p>他说，你这里而放着一个别人落的东西，你是不是天天看。</p><p>我说，我不开抽屉我就不看。</p><p>他说，你今天这个抽屉里东西的形状，跟你去年那个抽屉不一样。</p><p>他说，你去年那个抽屉里全是数据线。</p><p>他说，你今年这个抽屉里有一个不属于你的东西。</p><p>我说，我就是放这儿。</p><p>他把螺丝刀拿走了。</p><p>他走到门口回了一句。</p><p>他说，你这个人存东西，你存的都是不能讲的事。</p><p>他说，你存一次就多一个不能讲。</p><p>他说，你存到你三十岁，你这个屋子里全是你不能讲话的人。</p><p>我那天晚上把那个纸包拿出来过一次。</p><p>我拿在手上。</p><p>那个纸包外边已经被抽屉里别的东西藏毛了。</p><p>我没有拆。</p><p>我又把它放回去了。</p><p>我放进去那一下我想明白了陈树那句。</p><p>我这四年存下来的东西，垒在一起，全部是为了不要开口。</p><p>我把那个抽屉推上。</p><p>我把那个杯盖在抽屉里放了六年。</p>',135)])])}const m=t(o,[["render",r]]);export{u as __pageData,m as default};
